"use client";
import { Swiper, SwiperSlide } from "swiper/react";
import { useHeroCarousel } from "../../react-query/hooks";
import { VITE_IMAGE_PATH_URL } from "../../react-query/constants";
import { Autoplay } from "swiper/modules";
import "swiper/css";

const Hero = () => {
  const { data, isLoading, error, isError } = useHeroCarousel();

  if (isError && error) {
    return (
      <header className="hero min-h-[50vh] bg-base-200 bg-no-repeat bg-center bg-cover bg-fixed">
        <div className="hero-content text-center">
          <p className="text-error">
            Oops something went wrong, try again {error instanceof Error ? error.message : "Unknown error"}
          </p>
        </div>
      </header>
    );
  }

  if (isLoading) {
    return <div className="skeleton h-[50vh] w-full rounded-none"></div>;
  }

  if (!data?.sliders || data.sliders.length === 0) {
    return (
      <header className="hero min-h-[50vh] bg-base-200">
        <div className="hero-content text-center">
          <p>No sliders available</p>
        </div>
      </header>
    );
  }

  return (
    <header className="min-h-[50vh] bg-base-200">
      <Swiper
        autoplay={{
          delay: 2500,
          disableOnInteraction: false,
        }}
        modules={[Autoplay]}
        className="heroSwiper h-[400px]"
      >
        {data.sliders.map((item) => (
          <SwiperSlide
            key={item.id}
            className="bg-no-repeat bg-center bg-cover"
            style={{
              backgroundImage: `url(${VITE_IMAGE_PATH_URL}/slider/${item.slider_img})`,
            }}
          />
        ))}
      </Swiper>
    </header>
  );
};

export default Hero;
